static void Bitmap(HWND window,const char* path){RECT bounds;GetWindowRect(window,&bounds);int width=bounds.right-bounds.left,height=bounds.bottom-bounds.top;BITMAPINFO info={};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=width;info.bmiHeader.biHeight=-height;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;void* pixels=NULL;HBITMAP bitmap=CreateDIBSection(NULL,&info,DIB_RGB_COLORS,&pixels,NULL,0);HDC dc=CreateCompatibleDC(NULL);auto old=SelectObject(dc,bitmap);RECT fill={0,0,width,height};FillRect(dc,&fill,(HBRUSH)(COLOR_BTNFACE+1));SendMessageW(window,WM_PRINT,(WPARAM)dc,PRF_CLIENT|PRF_NONCLIENT|PRF_CHILDREN|PRF_ERASEBKGND);GdiFlush();BITMAPFILEHEADER header={};header.bfType=0x4d42;header.bfOffBits=sizeof(header)+sizeof(info.bmiHeader);header.bfSize=header.bfOffBits+width*height*4;std::ofstream out(path,std::ios::binary);out.write((char*)&header,sizeof(header));out.write((char*)&info.bmiHeader,sizeof(info.bmiHeader));out.write((char*)pixels,width*height*4);SelectObject(dc,old);DeleteDC(dc);DeleteObject(bitmap);}
